public boolean shouldPrintMessage(int timestamp, String message) {
    // Validate inputs
    if (message == null || timestamp < 0) {
        return false;
    }

    // Retrieve the last printed timestamp for this message
    Integer lastTimestamp = lastPrinted.get(message);

    // If the message hasn't been printed before or it's been at least 10 seconds,
    // allow printing and update the timestamp.
    if (lastTimestamp == null || timestamp - lastTimestamp >= 10) {
        lastPrinted.put(message, timestamp);
        return true;
    }

    // Otherwise, block the message
